const rawTopic = String(msg.topic || '');
const parts = rawTopic.split('/');
if (parts.length !== 4 || parts[0] !== 'latticedx' || parts[3] !== 'telemetry') {
  node.warn('Ignored invalid IIoT telemetry topic: ' + rawTopic);
  return null;
}
const orgId = parts[1].trim();
const topicAsset = parts[2].trim();
if (!/^[a-zA-Z0-9_-]{1,80}$/.test(orgId)) {
  node.warn('Rejected invalid organizationId in topic: ' + orgId);
  return null;
}
let data = msg.payload;
if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (err) {
    node.warn('Invalid JSON telemetry payload: ' + err.message);
    return null;
  }
}
if (!data || typeof data !== 'object' || Array.isArray(data)) {
  node.warn('Telemetry payload must be a JSON object');
  return null;
}
const rawValue = data.numericValue !== undefined ? data.numericValue : data.value;
if (rawValue === null || rawValue === undefined || (typeof rawValue === 'string' && rawValue.trim() === '') || typeof rawValue === 'boolean' || typeof rawValue === 'object') {
  node.warn('Missing or non-numeric telemetry value');
  return null;
}
const numericValue = Number(rawValue);
if (!Number.isFinite(numericValue)) {
  node.warn('Non-finite telemetry numericValue');
  return null;
}
const edgeToken = String(env.get('DX_IIOT_INGEST_TOKEN') || '').trim();
if (edgeToken.length < 16) {
  node.error('DX_IIOT_INGEST_TOKEN missing or shorter than 16 chars; refusing telemetry dispatch');
  return null;
}
const metricName = String(data.metricName || data.attribute || 'temperature').trim();
if (!/^[a-zA-Z0-9_.-]{1,128}$/.test(metricName)) {
  node.warn('Invalid metricName: ' + metricName);
  return null;
}
const assetId = data.assetId != null && /^[1-9]\d{0,18}$/.test(String(data.assetId)) ? Number(data.assetId) : undefined;
const assetEntityId = String(data.assetEntityId || (/^[1-9]\d{0,18}$/.test(topicAsset) ? 'urn:ngsi-ld:Asset:' + orgId + ':native:' + topicAsset : topicAsset)).trim().slice(0, 255);
if (!assetEntityId) {
  node.warn('Missing assetEntityId');
  return null;
}
let observedAt;
if (data.observedAt != null && data.observedAt !== '') {
  const dt = new Date(String(data.observedAt));
  if (!Number.isFinite(dt.getTime())) {
    node.warn('Invalid observedAt timestamp');
    return null;
  }
  observedAt = dt.toISOString();
} else {
  observedAt = new Date().toISOString();
}
msg.url = String(env.get('DX_IIOT_INGEST_URL') || 'http://nocobase/api/dxosBlocks:telemetryIngest').trim();
msg.headers = {
  'Content-Type': 'application/json',
  'X-Lattice-Edge-Token': edgeToken
};
msg.payload = {
  organizationId: orgId,
  ...(assetId !== undefined ? { assetId } : {}),
  assetEntityId,
  metricName,
  numericValue,
  unit: String(data.unit || 'CEL').trim().slice(0, 64) || 'CEL',
  quality: String(data.quality || 'good').trim().slice(0, 64) || 'good',
  sourceProtocol: 'mqtt',
  observedAt
};
return msg;
